<?php
require_once __DIR__.'/common.php';cron_start('process_queue',1800);$scheduler=new Scheduler($db);$pending=$db->all("SELECT * FROM videos WHERE status IN ('Pending','Retry') AND (next_retry_at IS NULL OR next_retry_at<=?) ORDER BY created_at ASC LIMIT 100",[now_sql()]);
foreach($pending as $v){try{$slot=$scheduler->scheduleVideo((int)$v['id']);if(!$slot)$services->log('WARNING','schedule.no_slot','No enabled schedule slot available',['video_id'=>$v['id']]);else $services->log('INFO','schedule.assigned','Video scheduled',['video_id'=>$v['id'],'scheduled_at_utc'=>$slot]);}catch(Throwable $e){$services->log('ERROR','schedule.failed',$e->getMessage(),['video_id'=>$v['id']]);}}
$lead=(int)($config['upload']['private_upload_lead_minutes']??10);$now=time();$due=$db->all("SELECT v.*,c.channel_name,c.status channel_status FROM videos v JOIN youtube_channels c ON c.id=v.youtube_channel_id WHERE v.status IN ('Scheduled','Queued') AND v.scheduled_at IS NOT NULL AND ((v.privacy_status='private' AND UNIX_TIMESTAMP(v.scheduled_at)<=?) OR (v.privacy_status<>'private' AND UNIX_TIMESTAMP(v.scheduled_at)<=?)) AND c.status='connected' ORDER BY v.scheduled_at ASC LIMIT 10",[$now+$lead*60,$now]);
foreach($due as $video){$tmp=null;$attemptId=null;try{$changed=$db->exec("UPDATE videos SET status='Uploading',updated_at=? WHERE id=? AND status IN ('Scheduled','Queued')",[now_sql(),$video['id']]);if($changed!==1)continue;$attemptNo=(int)$video['retry_count']+1;$attemptId=$db->insert('INSERT INTO upload_attempts(video_id,attempt_number,started_at) VALUES(?,?,?)',[$video['id'],$attemptNo,now_sql()]);$folder=$db->one('SELECT * FROM drive_folders WHERE id=? AND enabled=1',[$video['drive_folder_id']]);if(!$folder)throw new RuntimeException('Drive folder mapping not found or disabled.');$space=(int)($config['upload']['max_temp_file_bytes']??0);$tmp=$config['upload']['temp_dir'].'/'.bin2hex(random_bytes(16)).'.upload';if(!is_dir(dirname($tmp))&&!mkdir(dirname($tmp),0750,true)&&!is_dir(dirname($tmp)))throw new RuntimeException('Cannot create temporary directory.');$drive=new GoogleDrive($services->tokenForDrive((int)$folder['drive_connection_id']));$drive->downloadTo($video['drive_file_id'],$tmp,$space);$channel=$db->one('SELECT * FROM youtube_channels WHERE id=?',[$video['youtube_channel_id']]);$meta=$services->renderMetadata($video,$channel);$yt=new YouTube($services->tokenForYoutube((int)$video['youtube_channel_id']),(int)$config['upload']['chunk_size']);$result=$yt->uploadResumable($tmp,$meta);$ytId=$result['id']??null;if(!$ytId)throw new RuntimeException('YouTube upload returned no video ID.');$db->exec("UPDATE videos SET status='Uploaded',youtube_video_id=?,uploaded_at=?,updated_at=?,last_error=NULL,next_retry_at=NULL WHERE id=?",[$ytId,now_sql(),now_sql(),$video['id']]);$db->exec('UPDATE upload_attempts SET finished_at=?,success=1,response_json=? WHERE id=?',[now_sql(),json_encode_safe($result),$attemptId]);$services->log('INFO','upload.complete','Upload completed',['video_id'=>$video['id'],'youtube_video_id'=>$ytId,'channel_id'=>$video['youtube_channel_id']]);}catch(Throwable $e){$retry=(int)$video['retry_count']+1;$transient=$services->transientError($e->getMessage());$max=(int)$config['upload']['max_retries'];$status=($transient&&$retry<=$max)?'Retry':'Failed';$next=$status==='Retry'?gmdate('Y-m-d H:i:s',time()+min(3600,120*(2**min($retry,5)))):null;$db->exec('UPDATE videos SET status=?,retry_count=?,next_retry_at=?,last_error=?,updated_at=? WHERE id=?',[$status,$retry,$next,$e->getMessage(),now_sql(),$video['id']]);if($attemptId)$db->exec('UPDATE upload_attempts SET finished_at=?,success=0,error_message=? WHERE id=?',[now_sql(),$e->getMessage(),$attemptId]);$services->log($status==='Retry'?'WARNING':'ERROR','upload.failed',$e->getMessage(),['video_id'=>$video['id'],'retry_count'=>$retry,'status'=>$status]);}finally{if($tmp&&is_file($tmp))@unlink($tmp);}}
